pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address firstOwner, address secondOwner) public {
        vm.assume(firstOwner != secondOwner);
        vm.assume(firstOwner != address(0));
        vm.assume(secondOwner != address(0));

        c.setOwner(firstOwner);
        c.setOwner(secondOwner);

        assertTrue(c.owner() == secondOwner);
    }
}
